    h, w = len(grid), len(grid[0])
    # Uniform horizontal bands encode a one-dimensional vertical cycle.
    row_constraints = {r: row[0] for r, row in enumerate(grid)
                      if row[0] != 0 and all(v == row[0] for v in row)}
    if row_constraints and len(row_constraints) == sum(1 for row in grid if any(row)):
        for period in range(1, h + 1):
            vals = {}
            valid = True
            for r, color in row_constraints.items():
                k = r % period
                if k in vals and vals[k] != color:
                    valid = False
                    break
                vals[k] = color
            if valid:
                known = sorted(vals)
                cycle = [None] * period
                for k, c in vals.items(): cycle[k] = c
                for k in range(period):
                    if cycle[k] is None:
                        # Complete unconstrained phases from the closest known phase.
                        near = min(known, key=lambda j: (min((k-j)%period, (j-k)%period), j))
                        cycle[k] = vals[near]
                return [[cycle[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the clues are diagonal bands: color is periodic in (column-row).
    clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in clues and clues[d] != color:
                    # Not expected for the ARC encodings, but retain a deterministic fallback.
                    continue
                clues[d] = color
    for period in range(1, h + w + 1):
        vals = {}
        valid = True
        for d, color in clues.items():
            k = d % period
            if k in vals and vals[k] != color:
